_study.AUTH_GSW = ("KI-Entwurf (Claude) vom 2026-10-18; aus dem Hochdeutschen in Züridüütsch gefasst; "
                   "Mundart noch nicht muttersprachlich geprüft.")

TAGS = ["TAG-MATTHEW"]
CHAPTERS = {22: "TU-MAT-022-001-046", 23: "TU-MAT-023-001-039", 24: "TU-MAT-024-001-051", 25: "TU-MAT-025-001-046",
            26: "TU-MAT-026-001-075", 27: "TU-MAT-027-001-066", 28: "TU-MAT-028-001-020"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-MAT-*.json"))


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    if ch not in CHAPTERS:
        raise SystemExit(f"Mt {ch} gehört nicht zu diesem Werkzeug")
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-MAT-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


# Bestehender Kontext, unverändert übernommen (write() schreibt dann nichts)
