# Hintergrund: (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, unsicher, Belege, Quellen, Fachwörter | Mundart)
BACKGROUND = [
 # Kapitel 22
 ("BG-MAT-4001", U(22, 15, 22), "MAT.22.17-MAT.22.21", TEMPLE, "probable", "Steuer für den Kaiser und Denar",
  "Seit Judäa im Jahr 6 n. Chr. unter direkte römische Verwaltung kam, schuldete es den Römern Steuern; der Statthalter von Syrien, Quirinius, liess dazu nach Josephus den Besitz der Bewohner schätzen (Zensus). Judas der Galiläer rief damals zum Widerstand auf: Wer den Römern Steuer zahle, erkenne neben Gott einen sterblichen Herrn an. Die Frage in [[MAT.22.17]] war darum gefährlich: Ein Nein machte Jesus bei den Römern verdächtig, ein Ja bei denen, die die Steuer als Verrat an Gott ansahen. Die Steuer wurde in römischem Silbergeld bezahlt; ein Denar war etwa der Tageslohn eines Arbeiters ([[MAT.20.2]]). Die Denare des Kaisers Tiberius trugen sein Bild und die Aufschrift «TI CAESAR DIVI AVG F AVGVSTVS» (Tiberius Caesar, Sohn des göttlichen Augustus, Augustus). Die Herodianer (BG-MRK-1007) standen dem Haus des Herodes und damit der römischen Ordnung nahe.",
  "Josephus spricht von einer Schätzung des Besitzes und von Abgaben an die Römer, nicht ausdrücklich von einer Kopfsteuer; dass dazu eine Kopfsteuer gehörte, wird oft angenommen (auch wegen des Wortes κῆνσος), ist aber aus den hier nachgeschlagenen Stellen nicht belegt. Welche Münze Jesus gezeigt wurde, sagt der Text nicht; der Tiberius-Denar ist eine naheliegende Vermutung. Wie weit Galiläa, das Herodes Antipas unterstand, von dieser Steuer betroffen war, ist unsicher; die Szene spielt in Jerusalem.",
  ["MAT.22.15-MAT.22.22", "MAT.20.2", "MRK.12.13-MRK.12.17", "ACT.5.37"],
  ["Josephus, Jüdische Altertümer 18,1–10", "Josephus, Jüdischer Krieg 2,117–118"],
  [("grc", "κῆνσος", "Steuer (lateinisch census)"), ("grc", "δηνάριον", "Denar, römische Silbermünze"), ("lat", "census", "Schätzung, Steuer", "census")],
  "Stüür für de Kaiser und Denar",
  "Sit Judäa im Jaar 6 n. Chr. under diräkti römischi Verwaltig cho isch, hät s de Römer Stüüre gschuldet; de Statthalter vo Syrie, de Quirinius, hät dezue nach em Josephus de Bsitz vo de Bewooner la schätze (Zensus). De Judas de Galiläer hät dazmal zum Widerstand ufgrüeft: Wer de Römer Stüür zali, erchänn näbed Gott en stärbliche Herr aa. D Frag i [[MAT.22.17]] isch drum gföörlich gsii: Es Nei hät de Jesus bi de Römer verdächtig gmacht, es Ja bi dene, wo d Stüür als Verraat a Gott aagluegt händ. D Stüür isch mit römischem Silbergält zalt worde; en Denar isch öppe de Taglohn vo me Arbeiter gsii ([[MAT.20.2]]). D Denar vom Kaiser Tiberius händ sis Bild treit und d Ufschrift «TI CAESAR DIVI AVG F AVGVSTVS» (Tiberius Caesar, Sohn vom göttliche Augustus, Augustus). D Herodianer (BG-MRK-1007) sind em Huus vom Herodes und dermit de römische Ornig nööch gstande.",
  "De Josephus redt vo ere Schätzig vom Bsitz und vo Abgaabe a d Römer, nöd usdrücklich vo ere Chopfstüür; dass e Chopfstüür dezue ghört hät, nimmt mer oft aa (au wäg em Wort κῆνσος), isch aber us de Stelle, wo da nachegluegt worde sind, nöd belegt. Weli Münz em Jesus zeigt worde isch, seit de Text nöd; de Tiberius-Denar isch e nööchligendi Vermuetig. Wie wiit Galiläa, wo under em Herodes Antipas gstande isch, vo de Stüür betroffe gsii isch, isch unsicher; d Szene spilt z Jerusalem.",
  ["Stüür (latiinisch census)", "Denar, römischi Silbermünz", "Schätzig, Stüür"]),
 ("BG-MAT-4002", U(22, 23, 33), "MAT.22.23-MAT.22.28", TEMPLE, "probable", "Sadduzäer und Schwagerehe",
  "Die Sadduzäer waren eine Gruppe, die vor allem in der Jerusalemer Priesteraristokratie verankert war. Nach Josephus lehnten sie ab, dass die Seele den Tod überdauert und dass es Lohn und Strafe nach dem Tod gibt, und anerkannten nur die schriftlich überlieferten Gesetze, nicht die Überlieferungen der Pharisäer; die Apostelgeschichte sagt, sie lehnten Auferstehung, Engel und Geist ab ([[ACT.23.8]]). Ihre Frage beruht auf der Schwagerehe (Levirat, [[DEU.25.5-DEU.25.10]]; vgl. [[GEN.38.8]]; [[RUT.4.5]]): Stirbt ein Mann kinderlos, soll sein Bruder die Witwe heiraten, damit der Name des Verstorbenen erhalten bleibt. Die Mischna widmet dem Thema den Traktat Jebamot. Jesus antwortet mit einem Wort aus der Tora selbst ([[EXO.3.6]]), also aus den Büchern, die auch die Sadduzäer anerkannten.",
  "Die Nachrichten über die Sadduzäer stammen fast nur von ihren Gegnern (Josephus, Neues Testament, rabbinische Texte). Ob sie wirklich nur die fünf Bücher Mose als Schrift gelten liessen, ist umstritten; Josephus spricht von den «geschriebenen» Gesetzen im Unterschied zur Überlieferung.",
  ["MAT.22.23-MAT.22.33", "DEU.25.5-DEU.25.10", "GEN.38.8", "RUT.4.5", "ACT.23.8", "EXO.3.6"],
  ["Josephus, Jüdische Altertümer 18,16–17", "Josephus, Jüdische Altertümer 13,297", "Josephus, Jüdischer Krieg 2,164–166",
   "Mischna, Traktat Jebamot"],
  [("grc", "Σαδδουκαῖος", "Sadduzäer"), ("heb", "יִבּוּם", "Schwagerehe, Levirat", "yibbûm")],
  "Sadduzäer und Schwagerehe",
  "D Sadduzäer sind e Gruppe gsii, wo vor allem i de Prieschteraristokratie vo Jerusalem verankeret gsii isch. Nach em Josephus händ si abglehnt, dass d Seel de Tod überduuret und dass es Lohn und Straf nach em Tod git, und händ nu di schriftlich überliferete Gsetz aaerchännt, nöd d Überliferige vo de Pharisäer; d Aposchtelgschicht seit, si hebed Uferstehig, Ängel und Geischt abglehnt ([[ACT.23.8]]). Iri Frag beruet uf de Schwagerehe (Levirat, [[DEU.25.5-DEU.25.10]]; vgl. [[GEN.38.8]]; [[RUT.4.5]]): Stirbt en Maa ohni Chind, söll sin Brüeder d Witwe hürate, damit de Name vom Verstorbne erhalte bliibt. D Mischna widmet em Thema de Traktat Jebamot. De Jesus antwortet mit eme Wort us de Tora sälber ([[EXO.3.6]]), also us de Büecher, wo au d Sadduzäer aaerchännt händ.",
  "D Nachrichte über d Sadduzäer stammed fascht nu vo irne Gägner (Josephus, Nöis Teschtamänt, rabbinischi Text). Öb si würkli nu di föif Büecher vom Mose als Schrift händ la gälte, isch umstritte; de Josephus redt vo de «gschribne» Gsetz im Underschid zur Überliferig.",
  ["Sadduzäer", "Schwagerehe, Levirat"]),
 ("BG-MAT-4003", U(22, 1, 14), "MAT.22.2-MAT.22.13", READERS, "possible", "Einladung zum königlichen Festmahl",
  "Ein Gastmahl war in der Antike ein öffentliches Ereignis, bei dem Ehre gewonnen oder verloren wurde. Dass Geladene zur Stunde des Mahls noch einmal gerufen werden ([[MAT.22.3-MAT.22.4]]), kennt auch das Buch Ester: Die Kämmerer des Königs holen Haman zum Mahl, zu dem Ester geladen hatte ([[EST.5.8]]; [[EST.6.14]]). Eine Absage im letzten Moment war eine Beleidigung des Gastgebers; Gewalt gegen seine Boten kam einem Aufstand gleich. Im Babylonischen Talmud steht ein Gleichnis, das Rabban Jochanan ben Sakkai zugeschrieben wird: Ein König lädt seine Knechte zu einem Mahl ohne festgesetzte Zeit; die Klugen schmücken sich und warten an der Tür, die Törichten gehen ihrer Arbeit nach; als der König ruft, kommen diese in schmutzigen Kleidern und dürfen nur zusehen.",
  "Das talmudische Gleichnis ist Jahrhunderte später niedergeschrieben; es zeigt ein verbreitetes Bild, keine Vorlage des Matthäus. Ob es Brauch war, dass Gastgeber Festkleider stellten, ist nicht sicher belegt (INT-MAT-4002).",
  ["MAT.22.1-MAT.22.14", "EST.5.8", "EST.6.14", "LUK.14.15-LUK.14.24"],
  ["Babylonischer Talmud, Schabbat 153a"],
  [("grc", "γάμος", "Hochzeit, Hochzeitsfest"), ("grc", "ἄριστον", "Mahl (eigentlich Frühmahl)")],
  "Iiladig zum königliche Fäschtässe",
  "Es Fäschtässe isch i de Antike es öffentlichs Ereignis gsii, wo mer Eer hät chöne gwünne oder verlüüre. Dass Iigladni zur Stund vom Ässe nomal grüeft wärded ([[MAT.22.3-MAT.22.4]]), kännt au s Buech Ester: D Chämmerer vom König holed de Haman zum Ässe, wo d Ester iiglade hät ([[EST.5.8]]; [[EST.6.14]]). E Absag im letschte Momänt isch e Beleidigung vom Gaschtgäber gsii; Gwalt gäge sini Bote isch wie en Ufstand gsii. Im Babylonische Talmud staat es Gliichnis, wo em Rabban Jochanan ben Sakkai zuegschribe wird: En König ladt sini Chnächt zu me Ässe ohni feschti Ziit ii; di Gschiide mached sich schöön und warted a de Tür, di Tumme gönd irer Arbet naa; wo de König rüeft, chömed die i dräckige Chleider und dörfed nu zueluege.",
  "S talmudisch Gliichnis isch Jaarhundert spööter ufgschribe worde; es zeigt es verbreitets Bild, kei Vorlag vom Matthäus. Öb s Bruuch gsii isch, dass Gaschtgäber Fäschtchleider gstellt händ, isch nöd sicher belegt (INT-MAT-4002).",
  ["Hochziit, Hochziitfäscht", "Ässe (eigentlich Zmorge)"]),
 ("BG-MAT-4004", U(22, 41, 46), "MAT.22.42-MAT.22.45", TEMPLE, "probable", "Davids Sohn und Psalm 110",
  "Dass der erwartete Gesalbte ein Nachkomme Davids sein werde, gründet auf der Verheissung an David ([[2SA.7.12-2SA.7.16]]) und auf Prophetenworten ([[ISA.11.1]]; [[JER.23.5]]). Die Psalmen Salomos aus dem 1. Jahrhundert v. Chr. bitten Gott, «ihren König, den Sohn Davids» aufstehen zu lassen. Matthäus nennt Jesus schon im ersten Vers «Sohn Davids» ([[MAT.1.1]]), und Hilfesuchende rufen ihn so an ([[MAT.9.27]]; [[MAT.15.22]]; [[MAT.20.30-MAT.20.31]]; [[MAT.21.9]]). [[PSA.110.1]], in der Überschrift David zugeschrieben, ist die im Neuen Testament am häufigsten zitierte oder angespielte Stelle der Schrift (etwa [[ACT.2.34-ACT.2.35]]; [[HEB.1.13]]); Jesus nimmt sie auch vor dem Hohen Rat auf ([[MAT.26.64]]).",
  "Ob die Davidssohn-Erwartung zur Zeit Jesu allgemein verbreitet war, ist umstritten; die Quellen zeigen verschiedene Erwartungen. Die Aussage über die Häufigkeit des Psalmzitats beruht auf gängigen Übersichten, nicht auf eigener Zählung.",
  ["MAT.22.41-MAT.22.46", "PSA.110.1", "2SA.7.12-2SA.7.16", "MAT.1.1", "MAT.26.64"],
  ["Psalmen Salomos 17,21"],
  [("grc", "υἱὸς Δαυίδ", "Sohn Davids")],
  "Em David sin Sohn und de Psalm 110",
  "Dass de erwartet Gsalbt en Nachkomme vom David seg, gründet uf de Verheissig a de David ([[2SA.7.12-2SA.7.16]]) und uf Prophetewort ([[ISA.11.1]]; [[JER.23.5]]). D Psalme vom Salomo us em 1. Jaarhundert v. Chr. bitted Gott, er söll «iren König, de Sohn vom David» la ufstaa. De Matthäus nännt de Jesus scho im erschte Värs «Sohn vom David» ([[MAT.1.1]]), und Lüüt, wo Hilf sueched, rüefed en eso aa ([[MAT.9.27]]; [[MAT.15.22]]; [[MAT.20.30-MAT.20.31]]; [[MAT.21.9]]). [[PSA.110.1]], i de Überschrift em David zuegschribe, isch d Stell us de Schrift, wo im Nöie Teschtamänt am hüüfigschte zitiert oder aagspilt wird (öppe [[ACT.2.34-ACT.2.35]]; [[HEB.1.13]]); de Jesus nimmt si au vor em Hohe Raat uf ([[MAT.26.64]]).",
  "Öb d Erwartig vom Davidssohn zur Ziit vo Jesus allgemein verbreitet gsii isch, isch umstritte; d Quälle zeiged verschideni Erwartige. D Ussag über d Hüüfigkeit vom Psalmzitat beruet uf gängige Übersichte, nöd uf eigeter Zellig.",
  ["Sohn vom David"]),
 # Kapitel 23
 ("BG-MAT-4005", U(23, 1, 12), "MAT.23.2", TEMPLE, "possible", "Der Stuhl des Mose",
  "«Auf dem Stuhl des Mose sitzen» meint, mit der Autorität des Mose das Gesetz zu lehren und auszulegen. In Synagogen von Chorazin, Hammat bei Tiberias und anderen Orten wurden steinerne Ehrensitze gefunden, die man mit dem «Stuhl des Mose» in Verbindung bringt; der Sitz aus Chorazin trägt eine aramäische Inschrift. Möglich ist, dass von einem solchen Sitz aus gelehrt oder aus der Tora vorgelesen wurde.",
  "Die gefundenen Sitze stammen aus späteren Jahrhunderten als das Evangelium; ob es im 1. Jahrhundert einen solchen Sitz gab oder ob der Ausdruck nur bildlich gemeint ist, ist offen.",
  ["MAT.23.2-MAT.23.3"], [],
  [("grc", "καθέδρα Μωϋσέως", "Stuhl, Lehrsitz des Mose")],
  "De Stuel vom Mose",
  "«Uf em Stuel vom Mose sitze» meint, mit de Autorität vom Mose s Gsetz lehre und uuslegge. I Synagoge vo Chorazin, Hammat bi Tiberias und andere Ort sind steinigi Eeresitz gfunde worde, wo mer mit em «Stuel vom Mose» in Verbindig bringt; de Sitz us Chorazin treit e aramäischi Inschrift. Möglich isch, dass vo me settige Sitz uus glehrt oder us de Tora vorgläse worde isch.",
  "Di gfundne Sitz stammed us spöötere Jaarhundert als s Evangelium; öb s im 1. Jaarhundert en settige Sitz ggää hät oder öb de Uusdruck nu bildlich gmeint isch, isch offe.",
  ["Stuel, Lehrsitz vom Mose"]),
 ("BG-MAT-4006", U(23, 1, 12), "MAT.23.5", TEMPLE, "probable", "Gebetsriemen und Quasten",
  "Die «Gebetsriemen» (griechisch φυλακτήρια, «Schutzmittel»; hebräisch tᵉfillîn) sind kleine Kapseln mit Schriftabschnitten auf Pergament, die mit Riemen an Arm und Stirn gebunden werden. Sie gehen auf das Gebot zurück, die Worte Gottes «als Zeichen auf deine Hand» und «zwischen deine Augen» zu binden ([[DEU.6.8]]; [[DEU.11.18]]; [[EXO.13.9]]; [[EXO.13.16]]). In den Höhlen von Qumran wurden solche Kapseln und beschriebene Streifen aus der Zeit vor 70 gefunden. Die «Quasten» (κράσπεδα, hebräisch ṣîṣit) sind Fäden an den vier Zipfeln des Obergewands ([[NUM.15.38-NUM.15.40]]; [[DEU.22.12]]); auch Jesus trug sie ([[MAT.9.20]]; [[MAT.14.36]]). Jesus kritisiert in [[MAT.23.5]] nicht den Brauch, sondern die Vergrösserung zur Schau.",
  "Das griechische Wort φυλακτήριον kann an Amulette denken lassen; ob Matthäus oder seine Leser die Kapseln so verstanden, ist unsicher. Wie verbreitet das Tragen im Alltag war, ist umstritten.",
  ["MAT.23.5", "DEU.6.8", "DEU.11.18", "EXO.13.9", "EXO.13.16", "NUM.15.38-NUM.15.40", "DEU.22.12", "MAT.9.20", "MAT.14.36"],
  ["Tefillin-Funde aus den Höhlen von Qumran"],
  [("grc", "φυλακτήριον", "Schutzmittel; Gebetsriemen"), ("heb", "תְּפִלִּין", "Gebetsriemen (Tefillin)", "tᵉfillîn"),
   ("grc", "κράσπεδον", "Saum, Quaste"), ("heb", "צִיצִת", "Quaste, Schaufaden", "ṣîṣit")],
  "Gebetsrieme und Quaste",
  "D «Gebetsrieme» (griechisch φυλακτήρια, «Schutzmittel»; hebräisch tᵉfillîn) sind chliini Kapsle mit Schriftabschnitt uf Pergament, wo mer mit Rieme a Arm und Stirn bindt. Si gönd uf s Gebot zrugg, d Wort vo Gott «als Zeiche uf dini Hand» und «zwüsche dini Auge» z binde ([[DEU.6.8]]; [[DEU.11.18]]; [[EXO.13.9]]; [[EXO.13.16]]). I de Höhline vo Qumran sind settigi Kapsle und beschribni Streife us de Ziit vor 70 gfunde worde. D «Quaste» (κράσπεδα, hebräisch ṣîṣit) sind Fäde a de vier Zipfel vom Obergwand ([[NUM.15.38-NUM.15.40]]; [[DEU.22.12]]); au de Jesus hät si treit ([[MAT.9.20]]; [[MAT.14.36]]). De Jesus kritisiert i [[MAT.23.5]] nöd de Bruuch, sondern s Vergrössere für d Show.",
  "S griechisch Wort φυλακτήριον cha a Amulett tänke laa; öb de Matthäus oder sini Läser d Kapsle eso verstande händ, isch unsicher. Wie verbreitet s Träge im Alltag gsii isch, isch umstritte.",
  ["Schutzmittel; Gebetsrieme", "Gebetsrieme (Tefillin)", "Saum, Quaste", "Quaste, Schaufade"]),
 ("BG-MAT-4007", U(23, 23, 28), "MAT.23.23-MAT.23.24", TEMPLE, "probable", "Der Zehnte von Gewürzkräutern; Mücke und Kamel",
  "Das Gesetz verlangt den Zehnten vom Ertrag des Landes ([[LEV.27.30]]; [[DEU.14.22-DEU.14.23]]). Die Mischna fasst die Regel so: Zehntpflichtig ist alles, was als Speise dient, gehütet wird und aus der Erde wächst; sie erörtert ausdrücklich auch den Dill. Wer selbst von Gewürzkräutern den Zehnten gab, nahm das Gebot sehr genau. Jesus kritisiert nicht diese Genauigkeit («dies hätte man tun … sollen»), sondern dass darüber «das Gewichtigere» vernachlässigt wird ([[MAT.23.23]]; vgl. [[MIC.6.8]]). Das Bild von Mücke und Kamel ([[MAT.23.24]]) spielt auf das Durchseihen von Getränken an: Die Mücke wie das Kamel galten als unrein ([[LEV.11.4]]; [[LEV.11.20-LEV.11.23]]; [[LEV.11.41-LEV.11.43]]).",
  "Ob auch Minze zehntpflichtig war, ist aus den Quellen nicht sicher. Ein oft genanntes aramäisches Wortspiel (qalmāʾ «Laus, Mücke» und gamlāʾ «Kamel») ist eine Vermutung.",
  ["MAT.23.23-MAT.23.24", "LEV.27.30", "DEU.14.22-DEU.14.23", "MIC.6.8", "LEV.11.4", "LEV.11.41-LEV.11.43", "LUK.11.42"],
  ["Mischna, Maaserot 1,1", "Mischna, Maaserot 4,5"],
  [("grc", "ἡδύοσμον", "Minze"), ("grc", "ἄνηθον", "Dill"), ("grc", "κύμινον", "Kümmel"), ("grc", "κώνωψ", "Mücke"),
   ("grc", "κάμηλος", "Kamel")],
  "De Zäänte vo Gwürzchrüüter; Mugge und Kamel",
  "S Gsetz verlangt de Zäänte vom Ertrag vom Land ([[LEV.27.30]]; [[DEU.14.22-DEU.14.23]]). D Mischna fasst d Regle eso: Zääntepflichtig isch alles, wo als Spiis dient, ghüetet wird und us de Ärde wachst; si redt usdrücklich au vom Dill. Wer sogar vo Gwürzchrüüter de Zäänte ggää hät, hät s Gebot sehr gnau gnoo. De Jesus kritisiert nöd die Gnauigkeit («das hett mer sölle tue»), sondern dass mer drob «s Gwichtiger» vernachlässiget ([[MAT.23.23]]; vgl. [[MIC.6.8]]). S Bild vo Mugge und Kamel ([[MAT.23.24]]) spilt uf s Duresiebe vo Getränk aa: D Mugge wie s Kamel händ als unrein gulte ([[LEV.11.4]]; [[LEV.11.20-LEV.11.23]]; [[LEV.11.41-LEV.11.43]]).",
  "Öb au Minze zääntepflichtig gsii isch, isch us de Quälle nöd sicher. Es oft gnännts aramäischs Wortspil (qalmāʾ «Luus, Mugge» und gamlāʾ «Kamel») isch e Vermuetig.",
  ["Minze", "Dill", "Chümi", "Mugge", "Kamel"]),
 ("BG-MAT-4008", U(23, 23, 28), "MAT.23.27-MAT.23.29", TEMPLE, "probable", "Getünchte Gräber und Prophetengräber",
  "Wer ein Grab berührte oder darüberging, wurde nach dem Gesetz unrein ([[NUM.19.16]]). Darum wurden Gräber mit Kalk markiert, damit niemand unwissentlich unrein wurde; die Mischna setzt diese Kennzeichnung voraus. Jesu Bild kehrt das um: Was aussen weiss und schön ist, verbirgt Totengebeine ([[MAT.23.27-MAT.23.28]]). Im Kidrontal östlich von Jerusalem stehen bis heute monumentale Grabbauten aus der Zeit des Zweiten Tempels, die später Absalom, Josafat und Sacharja zugeschrieben wurden. Solche Bauten zeigen, dass man Gräber verehrter Personen prachtvoll gestaltete ([[MAT.23.29]]).",
  "Die Zuschreibung der Kidron-Gräber an biblische Personen ist spätere Überlieferung. Dass die Gräber jedes Jahr im Frühling neu gekennzeichnet wurden, stützt sich auf die Mischna, die dafür den 15. Adar nennt, einen Monat vor dem Passafest (Schekalim 1,1); ob das schon zur Zeit Jesu so geschah, ist offen.",
  ["MAT.23.27-MAT.23.31", "NUM.19.16", "LUK.11.44", "LUK.11.47-LUK.11.48"],
  ["Mischna, Maaser Scheni 5,1", "Mischna, Schekalim 1,1"],
  [("grc", "κονιάω", "mit Kalk tünchen"), ("grc", "τάφος", "Grab"), ("grc", "μνημεῖον", "Grabmal, Gedenkstätte")],
  "Wiissgstricheni Greber und Prophetegreber",
  "Wer es Grab berüert hät oder drüber gloffe isch, isch nach em Gsetz unrein worde ([[NUM.19.16]]). Drum hät mer Greber mit Chalch markiert, damit niemer unwüssentlich unrein worde isch; d Mischna setzt die Kännzeichnig vorus. S Bild vo Jesus chehrt das um: Was usse wiiss und schöön isch, versteckt Totechnoche ([[MAT.23.27-MAT.23.28]]). Im Kidrontal öschtlich vo Jerusalem stönd bis hüt monumentali Grabbaute us de Ziit vom Zweite Tämpel, wo spööter em Absalom, em Josafat und em Sacharja zuegschribe worde sind. Settigi Baute zeiged, dass mer Greber vo verehrte Persone prächtig gstaltet hät ([[MAT.23.29]]).",
  "D Zueschriibig vo de Kidron-Greber a biblischi Persone isch spööteri Überliferig. Dass d Greber jedes Jaar im Früelig nöi kännzeichnet worde sind, stützt sich uf d Mischna, wo defür de 15. Adar nännt, en Monet vor em Passafäscht (Schekalim 1,1); öb das scho zur Ziit vo Jesus eso gsii isch, isch offe.",
  ["mit Chalch wiisse", "Grab", "Grabmal, Gedänkstätt"]),
 ("BG-MAT-4009", U(23, 29, 36), "MAT.23.35", READERS, "possible", "Von Abel bis Secharja",
  "In der hebräischen Bibel, wie sie im Judentum überliefert ist, stehen die Chronikbücher am Schluss. Wenn Matthäus an den Secharja aus [[2CH.24.20-2CH.24.22]] denkt, spannt «von Abel bis Secharja» den Bogen vom ersten bis zum letzten in der Schrift erzählten Mord an einem Gerechten. Beide Morde verbindet zudem der Ruf nach Vergeltung: Abels Blut schreit vom Erdboden ([[GEN.4.10]]), Secharja sagt sterbend: «Der HERR möge es sehen und einfordern» ([[2CH.24.22]]).",
  "Die Reihenfolge der Bücher mit der Chronik am Ende ist erst in späteren Quellen sicher belegt (etwa Babylonischer Talmud, Baba Batra 14b); ob sie im 1. Jahrhundert schon fest war, ist offen. Zur Identität des Secharja siehe QUESTION-MAT-4003.",
  ["MAT.23.35", "GEN.4.8-GEN.4.10", "2CH.24.20-2CH.24.22", "LUK.11.50-LUK.11.51"],
  ["Babylonischer Talmud, Baba Batra 14b"],
  [],
  "Vom Abel bis zum Secharja",
  "I de hebräische Bible, wie si im Judetum überliferet isch, stönd d Chronikbüecher am Schluss. Wänn de Matthäus a de Secharja us [[2CH.24.20-2CH.24.22]] tänkt, spannt «vom Abel bis zum Secharja» de Boge vom erschte bis zum letschte Mord a me Grächte, wo i de Schrift verzellt wird. Beid Mord verbindet usserdem de Ruef nach Vergältig: S Bluet vom Abel schreit vom Ärdbode ([[GEN.4.10]]), de Secharja seit, wo n er stirbt: «De HERR söll s gseh und iifordere» ([[2CH.24.22]]).",
  "D Reiefolg vo de Büecher mit de Chronik am Änd isch erscht i spöötere Quälle sicher belegt (öppe Babylonischer Talmud, Baba Batra 14b); öb si im 1. Jaarhundert scho fescht gsii isch, isch offe. Zur Identität vom Secharja lueg QUESTION-MAT-4003.",
  []),
 # Kapitel 24
 ("BG-MAT-4010", U(24, 15, 28), "MAT.24.15", TEMPLE, "probable", "Der «Gräuel der Verwüstung»",
  "Der Ausdruck stammt aus dem Buch Daniel ([[DAN.9.27]]; [[DAN.11.31]]; [[DAN.12.11]]) und meinte dort die Entweihung des Tempels unter dem Seleukidenkönig Antiochos IV.: Im Jahr 167 v. Chr. wurde auf dem Brandopferaltar ein heidnischer Altar errichtet, den das erste Makkabäerbuch ebenfalls «Gräuel der Verwüstung» nennt ([[1MA.1.54]]). Im Jahr 40 n. Chr. wollte Kaiser Caligula seine Statue im Jerusalemer Tempel aufstellen lassen; der Plan scheiterte am Widerstand der Juden und am Tod des Kaisers. Nach der Eroberung des Tempels im Jahr 70 stellten römische Soldaten nach Josephus ihre Feldzeichen im Tempelbezirk auf und opferten ihnen. Leser des Matthäus konnten «an heiliger Stätte» ([[MAT.24.15]]) auf diese Erfahrungen beziehen.",
  "Worauf Jesus oder Matthäus den Ausdruck bezog (auf eine erwartete Entweihung, auf die Ereignisse von 70 oder auf eine Gestalt der Endzeit), ist umstritten.",
  ["MAT.24.15-MAT.24.22", "DAN.9.27", "DAN.11.31", "DAN.12.11", "1MA.1.54", "MRK.13.14"],
  ["Josephus, Jüdische Altertümer 18,261–309", "Josephus, Jüdischer Krieg 2,184–203", "Josephus, Jüdischer Krieg 6,316"],
  [("grc", "βδέλυγμα τῆς ἐρημώσεως", "Gräuel der Verwüstung"), ("heb", "שִׁקּוּץ מְשֹׁמֵם", "verwüstender Gräuel (Daniel)", "šiqqûṣ mᵉšōmēm")],
  "De «Gröiel vo de Verwüeschtig»",
  "De Uusdruck stammt us em Buech Daniel ([[DAN.9.27]]; [[DAN.11.31]]; [[DAN.12.11]]) und hät det d Entweihig vom Tämpel underem Seleukidekönig Antiochos IV. gmeint: Im Jaar 167 v. Chr. isch uf em Brandopferaltar en heidnische Altar ufgstellt worde, wo s erscht Makkabäerbuech au «Gröiel vo de Verwüeschtig» nännt ([[1MA.1.54]]). Im Jaar 40 n. Chr. hät de Kaiser Caligula sini Statue im Tämpel vo Jerusalem wele la ufstelle; de Plan isch am Widerstand vo de Jude und am Tod vom Kaiser gscheiteret. Nach de Eroberig vom Tämpel im Jaar 70 händ römischi Soldate nach em Josephus iri Fäldzeiche im Tämpelbezirk ufgstellt und ene gopferet. Läser vom Matthäus händ «am heilige Ort» ([[MAT.24.15]]) chöne uf die Erfaarige bezieh.",
  "Uf was de Jesus oder de Matthäus de Uusdruck bezoge händ (uf e erwarteti Entweihig, uf d Ereignis vo 70 oder uf e Gstalt vo de Endziit), isch umstritte.",
  ["Gröiel vo de Verwüeschtig", "verwüeschtende Gröiel (Daniel)"]),
 ("BG-MAT-4011", U(24, 3, 14), "MAT.24.8", READERS, "possible", "Der «Anfang der Wehen»",
  "Das Bild der Geburtswehen steht in der Schrift für eine Not, die plötzlich kommt und unausweichlich ist, aus der aber Neues hervorgeht ([[ISA.26.17-ISA.26.19]]; [[ISA.66.7-ISA.66.9]]; [[JER.30.6-JER.30.7]]); Paulus gebraucht es für das plötzliche Kommen des Tages des Herrn ([[1TH.5.3]]). Rabbinische Texte sprechen später von den «Wehen des Messias», den Nöten vor seinem Kommen. «Anfang der Wehen» ([[MAT.24.8]]) sagt demnach: Kriege, Hungersnöte und Erdbeben sind noch nicht das Ende, sondern erst sein Beginn.",
  "Die Wendung «Wehen des Messias» ist erst in späteren Quellen belegt; ob sie im 1. Jahrhundert schon fester Begriff war, ist unsicher.",
  ["MAT.24.6-MAT.24.8", "ISA.26.17-ISA.26.19", "ISA.66.7-ISA.66.9", "JER.30.6-JER.30.7", "1TH.5.3", "MRK.13.8"],
  ["Babylonischer Talmud, Sanhedrin 98b"],
  [("grc", "ὠδίν", "Geburtswehe"), ("heb", "חֶבְלֵי הַמָּשִׁיחַ", "Wehen des Messias (rabbinisch)", "ḥevlê ham-māšîaḥ")],
  "De «Aafang vo de Wehe»",
  "S Bild vo de Geburtswehe staat i de Schrift für e Not, wo plötzlich chunnt und wo mer nöd cha uswiiche, us dere aber Nöis usechunnt ([[ISA.26.17-ISA.26.19]]; [[ISA.66.7-ISA.66.9]]; [[JER.30.6-JER.30.7]]); de Paulus bruucht s für d plötzlich Aachunft vom Tag vom Herr ([[1TH.5.3]]). Rabbinischi Text reded spööter vo de «Wehe vom Messias», vo de Nööt vor sinere Aachunft. «Aafang vo de Wehe» ([[MAT.24.8]]) seit also: Chrieg, Hungersnööt und Ärdbebe sind no nöd s Änd, sondern erscht sin Aafang.",
  "D Wändig «Wehe vom Messias» isch erscht i spöötere Quälle belegt; öb si im 1. Jaarhundert scho en feschte Begriff gsii isch, isch unsicher.",
  ["Geburtswehe", "Wehe vom Messias (rabbinisch)"]),
 ("BG-MAT-4012", U(24, 15, 28), "MAT.24.16-MAT.24.20", READERS, "possible", "Flucht in die Berge",
  "Die Mahnung, aus Judäa «in die Berge» zu fliehen, ohne noch etwas aus dem Haus zu holen ([[MAT.24.16-MAT.24.18]]), erinnert an Fluchtberichte der Schrift ([[GEN.19.17]]) und an die Makkabäerzeit, als Mattatias und seine Söhne in die Berge flohen ([[1MA.2.28]]). Eusebius berichtet, die Gemeinde in Jerusalem sei vor dem Krieg gegen Rom aufgrund eines Offenbarungsspruchs nach Pella im Ostjordanland ausgewandert. Die Bitte, die Flucht möge nicht im Winter (Regenzeit, schwer passierbare Wege) und nicht am Sabbat geschehen ([[MAT.24.20]]), setzt Leser voraus, denen die Sabbatruhe wichtig war.",
  "Ob der Bericht des Eusebius zuverlässig ist, ist umstritten; er schrieb im 4. Jahrhundert. Ob der Sabbat in [[MAT.24.20]] wegen der Gebote oder wegen geschlossener Stadttore und fehlender Hilfe genannt ist, ist offen.",
  ["MAT.24.16-MAT.24.20", "GEN.19.17", "1MA.2.28", "MRK.13.14-MRK.13.18"],
  ["Eusebius, Kirchengeschichte 3,5,3"],
  [],
  "Flucht i d Bärg",
  "D Mahnig, us Judäa «i d Bärg» z flüchte, ohni no öppis us em Huus z hole ([[MAT.24.16-MAT.24.18]]), erinneret a Fluchtbrichte vo de Schrift ([[GEN.19.17]]) und a d Makkabäerziit, wo de Mattatias und sini Söön i d Bärg gflüchtet sind ([[1MA.2.28]]). De Eusebius bricht, d Gmeind z Jerusalem seg vor em Chrieg gäge Rom wäge me Offebarigsspruch nach Pella im Oschtjordanland uusgwanderet. D Bitt, d Flucht söll nöd im Winter (Rägeziit, Wäg, wo mer schlächt dure chunnt) und nöd am Sabbat passiere ([[MAT.24.20]]), setzt Läser vorus, wo d Sabbatrue wichtig gsii isch.",
  "Öb de Bricht vom Eusebius zueverlässig isch, isch umstritte; er hät im 4. Jaarhundert gschribe. Öb de Sabbat i [[MAT.24.20]] wäge de Gebot oder wäge zuene Stadttor und fehlender Hilf gnännt isch, isch offe.",
  []),
 # Kapitel 25
 ("BG-MAT-4013", U(25, 1, 13), "MAT.25.1-MAT.25.10", TEMPLE, "possible", "Hochzeit und Lampen",
  "Zu einer jüdischen Hochzeit gehörte ein Festzug, in dem die Braut am Abend ins Haus des Bräutigams geführt wurde, oft mit Musik und Lichtern; das erste Makkabäerbuch erzählt von einem prächtigen Hochzeitszug, bei dem der Bräutigam mit Freunden und Brüdern und mit Pauken der Braut entgegenzog ([[1MA.9.37-1MA.9.39]]). Das griechische λαμπάς kann eine Öllampe oder eine Fackel bezeichnen; Fackeln aus ölgetränkten Lappen mussten bei langem Warten neu getränkt werden, kleine Tonlampen brauchten Nachfüllöl. Dass der Bräutigam um Mitternacht kommt ([[MAT.25.6]]) und die Tür danach verschlossen wird ([[MAT.25.10]]), sind Züge der Erzählung.",
  "Die Hochzeitsbräuche des 1. Jahrhunderts sind nur bruchstückhaft bekannt, vieles stammt aus späteren Quellen; welche Rolle unverheiratete Mädchen genau hatten, ist unsicher.",
  ["MAT.25.1-MAT.25.13", "1MA.9.37-1MA.9.39", "MAT.9.15"], [],
  [("grc", "λαμπάς", "Fackel, Lampe"), ("grc", "νυμφίος", "Bräutigam"), ("grc", "παρθένος", "junge, unverheiratete Frau; Jungfrau")],
  "Hochziit und Lampe",
  "Zu ere jüdische Hochziit hät en Fäschtzug ghört, wo d Brut am Aabig is Huus vom Brüütigam gfüert worde isch, oft mit Musig und Liechter; s erscht Makkabäerbuech verzellt vo me prächtige Hochziitzug, wo de Brüütigam mit Fründ und Brüedere und mit Pauke de Brut entgäge zoge isch ([[1MA.9.37-1MA.9.39]]). S griechisch λαμπάς cha e Ööllampe oder e Fackle bezeichne; Fackle us öölgtränkte Lumpe händ bim lange Warte nöi müese tränkt wärde, chliini Toonlampe händ Nachfüllööl bruucht. Dass de Brüütigam um Mitternacht chunnt ([[MAT.25.6]]) und d Tür nachher zueglosse wird ([[MAT.25.10]]), sind Züüg vo de Gschicht.",
  "D Hochziitbrüüch vom 1. Jaarhundert sind nu bruchstückhaft bekannt, vil stammt us spöötere Quälle; weli Rolle unghüraateti Meitli gnau ghaa händ, isch unsicher.",
  ["Fackle, Lampe", "Brüütigam", "jungi, unghüraateti Frau; Jumpfere"]),
 ("BG-MAT-4014", U(25, 14, 30), "MAT.25.15", TEMPLE, "probable", "Das Talent",
  "Ein Talent war ursprünglich eine Gewichtseinheit (je nach Region etwa 26 bis über 40 Kilogramm) und dann eine Rechnungseinheit für Silber; ein Talent entsprach etwa 6000 Drachmen oder Denaren. Bei einem Tageslohn von einem Denar ([[MAT.20.2]]) war schon ein einziges Talent der Lohn vieler Jahre. Geld bei Geldwechslern gegen Zinsen anzulegen ([[MAT.25.27]]) war im griechisch-römischen Wirtschaftsleben üblich; das Gesetz verbot Zinsen unter Israeliten, erlaubte sie aber von Fremden ([[DEU.23.19-DEU.23.20]]). Das Vergraben galt als sichere Verwahrung: Wer anvertrautes Geld vergrub, haftete nach späterem rabbinischem Recht nicht für den Verlust: Geld werde nur in der Erde wirklich verwahrt (Babylonischer Talmud, Baba Mezia 42a).",
  "Gewicht und Wert schwankten nach Ort und Zeit; die Umrechnung in Tageslöhne ist eine grobe Schätzung. Die rabbinische Regel zum Vergraben ist Jahrhunderte später niedergeschrieben; ob sie schon zur Zeit Jesu galt, ist offen.",
  ["MAT.25.14-MAT.25.30", "MAT.18.24", "MAT.20.2", "DEU.23.19-DEU.23.20", "LUK.19.11-LUK.19.27"],
  ["Babylonischer Talmud, Baba Mezia 42a"],
  [("grc", "τάλαντον", "Talent: Gewichts- und Geldeinheit"), ("grc", "τραπεζίτης", "Geldwechsler, Bankier"), ("grc", "τόκος", "Zins")],
  "S Talänt",
  "Es Talänt isch ursprünglich e Gwichtsiiheit gsii (je nach Region öppe 26 bis über 40 Kilo) und dänn e Rächnigsiiheit für Silber; es Talänt hät öppe 6000 Drachme oder Denar entsproche. Bi me Taglohn vo eim Denar ([[MAT.20.2]]) isch scho es einzigs Talänt de Lohn vo vile Jaar gsii. Gält bi Gältwächsler gäge Zins aazlegge ([[MAT.25.27]]) isch im griechisch-römische Wirtschaftsläbe üblich gsii; s Gsetz hät Zins under Israelite verbote, aber vo Frömde erlaubt ([[DEU.23.19-DEU.23.20]]). S Vergrabe hät als sicheri Ufbewaarig gulte: Wer aavertrauts Gält vergrabe hät, hät nach spööterem rabbinischem Rächt nöd für de Verluscht ghaftet: Gält werd nu i de Ärde würkli ufbewaart (Babylonische Talmud, Baba Mezia 42a).",
  "Gwicht und Wärt händ nach Ort und Ziit gschwankt; d Umrächnig i Taglööhn isch e groobi Schätzig. Di rabbinisch Regle zum Vergrabe isch Jaarhundert spööter ufgschribe; öb si scho zur Ziit vo Jesus gulte hät, isch offe.",
  ["Talänt: Gwichts- und Gältiiheit", "Gältwächsler, Bankier", "Zins"]),
 ("BG-MAT-4015", U(25, 31, 46), "MAT.25.32-MAT.25.33", GAL, "possible", "Schafe und Böcke",
  "Im Land Israel weideten Schafe und Ziegen oft in gemischten Herden. Ein Hirt konnte sie trennen, etwa weil Ziegen nachts mehr Wärme brauchen als Schafe; das ist allerdings eine Beobachtung aus späterer Zeit. Das Bild Gottes, der als Hirt zwischen Tieren seiner Herde richtet, steht in [[EZK.34.17]]: «Ich richte zwischen Schaf und Schaf, zwischen Widdern und Böcken.» Die rechte Seite galt als Ehrenplatz ([[PSA.110.1]]; vgl. [[MAT.20.21]]).",
  "Ob die Böcke wegen ihres Werts oder ihrer Eigenschaften für die Linke stehen, ist nicht zu entscheiden; das Bild lebt vor allem von der Trennung selbst.",
  ["MAT.25.31-MAT.25.46", "EZK.34.17", "PSA.110.1", "MAT.20.21"], [],
  [("grc", "πρόβατον", "Schaf"), ("grc", "ἔριφος", "Ziegenbock, Böcklein")],
  "Schaf und Böck",
  "Im Land Israel händ Schaf und Geisse oft i gmischte Herde gweidet. En Hirt hät si chöne tränne, öppe wil Geisse znacht meh Wärmi bruuched als Schaf; das isch allerdings e Beobachtig us spööterer Ziit. S Bild vo Gott, wo als Hirt zwüsche de Tier vo sinere Herde richtet, staat i [[EZK.34.17]]: «Ich richte zwüsche Schaf und Schaf, zwüsche Widder und Böck.» Di rächt Siite hät als Eereplatz gulte ([[PSA.110.1]]; vgl. [[MAT.20.21]]).",
  "Öb d Böck wäge irem Wärt oder irne Eigeschafte für di lingg Siite stönd, cha mer nöd entscheide; s Bild läbt vor allem vo de Trännig sälber.",
  ["Schaf", "Geissbock, Böckli"]),
 # Kapitel 26
 ("BG-MAT-4016", U(26, 14, 16), "MAT.26.15", TEMPLE, "possible", "Dreissig Silberstücke",
  "Dreissig Schekel Silber sind im Gesetz die Entschädigung, die für einen getöteten Sklaven an seinen Herrn zu zahlen ist ([[EXO.21.32]]). In [[ZEC.11.12-ZEC.11.13]] wird dem Hirten als Lohn dieser Betrag abgewogen, und er wirft ihn «dem Töpfer» im Haus des HERRN hin. Matthäus übernimmt aus Sacharja das Verb «abwiegen» (ἵστημι, [[MAT.26.15]]) und kommt in [[MAT.27.9-MAT.27.10]] auf die Stelle zurück. Welche Münzen gemeint sind, sagt der Text nicht; oft wird an tyrische Schekel gedacht, die als Silbermünzen in Jerusalem umliefen.",
  "Die Kaufkraft lässt sich nur grob schätzen. Ob die Summe historisch ist oder von Sacharja her genannt wird, ist umstritten.",
  ["MAT.26.14-MAT.26.16", "MAT.27.3-MAT.27.10", "EXO.21.32", "ZEC.11.12-ZEC.11.13"], [],
  [("grc", "ἀργύριον", "Silber, Silberstück, Geld"), ("heb", "שֶׁקֶל", "Schekel (Gewicht, Münze)", "šeqel")],
  "Driissg Silberstück",
  "Driissg Schekel Silber sind im Gsetz d Entschädigung, wo mer für en tötete Sklav sim Herr mues zale ([[EXO.21.32]]). I [[ZEC.11.12-ZEC.11.13]] wird em Hirt als Lohn dä Betrag abgwoge, und er rüert en «em Töpfer» im Huus vom HERR häre. De Matthäus übernimmt vom Sacharja s Verb «abwääge» (ἵστημι, [[MAT.26.15]]) und chunnt i [[MAT.27.9-MAT.27.10]] uf d Stell zrugg. Weli Münze gmeint sind, seit de Text nöd; oft tänkt mer a tyrischi Schekel, wo als Silbermünze z Jerusalem umegange sind.",
  "D Chaufchraft cha mer nu grob schätze. Öb d Summe historisch isch oder vom Sacharja här gnännt wird, isch umstritte.",
  ["Silber, Silberstück, Gält", "Schekel (Gwicht, Münz)"]),
 ("BG-MAT-4017", U(26, 26, 30), "MAT.26.30", TEMPLE, "probable", "Der Lobgesang nach dem Passamahl",
  "Nach der Mischna wurde beim Passamahl das Hallel gesungen, die Psalmen 113–118: ein Teil vor dem Mahl, der Rest nach dem letzten Becher; über die Grenze zwischen beiden Teilen stritten die Schulen Schammais und Hillels. Der «Lobgesang» in [[MAT.26.30]] meint darum wahrscheinlich den zweiten Teil des Hallel. Er endet mit [[PSA.118.22-PSA.118.29]], mit dem Stein, den die Bauleute verworfen haben, und dem Ruf «Gesegnet sei, der kommt im Namen des HERRN», den Jesus schon aufgenommen hat ([[MAT.21.9]]; [[MAT.21.42]]; [[MAT.23.39]]). Zum Passa selbst siehe BG-MRK-2004.",
  "Die Mischna ist um 200 n. Chr. niedergeschrieben; wie weit sie den Brauch vor 70 wiedergibt, ist umstritten. Ob das letzte Mahl Jesu ein Passamahl war, wird verschieden beurteilt (vgl. [[JHN.18.28]]).",
  ["MAT.26.26-MAT.26.30", "PSA.113.1-PSA.118.29", "MAT.21.9", "MAT.21.42", "MAT.23.39", "MRK.14.26"],
  ["Mischna, Pesachim 10,5–7"],
  [("grc", "ὑμνέω", "einen Lobgesang singen"), ("heb", "הַלֵּל", "Hallel: Lobpsalmen 113–118", "hallēl")],
  "De Lobgsang nach em Passamahl",
  "Nach de Mischna isch bim Passamahl s Hallel gsunge worde, d Psalme 113–118: en Teil vor em Ässe, de Räscht nach em letschte Bächer; über d Gränze zwüsche beidne Teil händ d Schuele vom Schammai und vom Hillel gstritte. De «Lobgsang» i [[MAT.26.30]] meint drum wahrschiinli de zweit Teil vom Hallel. Er hört uf mit [[PSA.118.22-PSA.118.29]], mit em Stei, wo d Buulüüt verworfe händ, und em Ruef «Gsägnet seg, wo chunnt im Name vom HERR», wo de Jesus scho ufgnoo hät ([[MAT.21.9]]; [[MAT.21.42]]; [[MAT.23.39]]). Zum Passa sälber lueg BG-MRK-2004.",
  "D Mischna isch um 200 n. Chr. ufgschribe worde; wie wiit si de Bruuch vor 70 widergit, isch umstritte. Öb s letscht Mahl vo Jesus es Passamahl gsii isch, wird verschide beurteilt (vgl. [[JHN.18.28]]).",
  ["en Lobgsang singe", "Hallel: Lobpsalme 113–118"]),
 ("BG-MAT-4018", U(26, 57, 68), "MAT.26.63-MAT.26.66", TEMPLE, "probable", "Lästerung und zerrissene Gewänder",
  "Wer den Namen Gottes lästert, soll nach [[LEV.24.16]] gesteinigt werden. Die Mischna beschreibt das Verfahren: Erst wenn der Zeuge die Lästerung mit dem Gottesnamen selbst wiederholt, stehen die Richter auf und zerreissen ihre Gewänder, ohne sie wieder zu nähen. Das Zerreissen der Kleider ist in der Schrift eine Geste der Trauer und des Entsetzens ([[2KI.18.37]]; [[2KI.19.1]]). Jesus gebraucht in [[MAT.26.64]] den Gottesnamen nicht, sondern umschreibt ihn mit «der Macht»; dass der Hohepriester trotzdem von Lästerung spricht, wird meist mit dem Anspruch erklärt, zur Rechten Gottes zu sitzen ([[PSA.110.1]]) und mit den Wolken zu kommen ([[DAN.7.13]]).",
  "Ob die Bestimmungen der Mischna, um 200 n. Chr. niedergeschrieben, schon für das Verfahren gegen Jesus galten, ist sehr unsicher. Zum Hohen Rat und seinen Befugnissen siehe BG-MRK-2007.",
  ["MAT.26.59-MAT.26.68", "LEV.24.16", "2KI.18.37", "2KI.19.1", "PSA.110.1", "DAN.7.13", "MRK.14.61-MRK.14.64"],
  ["Mischna, Sanhedrin 7,5"],
  [("grc", "βλασφημέω", "lästern"), ("grc", "διαρρήγνυμι", "zerreissen")],
  "Lästerig und verrissni Gwänder",
  "Wer de Name vo Gott lästeret, söll nach [[LEV.24.16]] gsteiniget wärde. D Mischna beschriibt s Verfahre: Erscht wänn de Züüg d Lästerig mit em Gottesname sälber widerholt, stönd d Richter uf und verriissed iri Gwänder, ohni si wider z näie. S Verriisse vo de Chleider isch i de Schrift e Geschte vo Truur und Entsetze ([[2KI.18.37]]; [[2KI.19.1]]). De Jesus bruucht i [[MAT.26.64]] de Gottesname nöd, sondern umschriibt en mit «de Macht»; dass de Hoheprieschter glich vo Lästerig redt, erklärt mer meischt mit em Aaspruch, rächts vo Gott z sitze ([[PSA.110.1]]) und mit de Wolke z cho ([[DAN.7.13]]).",
  "Öb d Bestimmige vo de Mischna, um 200 n. Chr. ufgschribe, scho fürs Verfahre gäge de Jesus gulte händ, isch sehr unsicher. Zum Hohe Raat und sine Befuegnis lueg BG-MRK-2007.",
  ["lästere", "verriisse"]),
 ("BG-MAT-4019", U(26, 69, 75), "MAT.26.73", GAL, "possible", "Die Sprechweise der Galiläer",
  "«Deine Sprechweise verrät dich» ([[MAT.26.73]]): Galiläer sprachen ein Aramäisch, das man in Jerusalem erkannte. Der Babylonische Talmud überliefert spätere Spottgeschichten über Galiläer, die die Kehllaute nicht unterschieden und darum missverstanden wurden. Matthäus fügt die Begründung hinzu, die bei Markus fehlt ([[MRK.14.70]]: «denn du bist auch ein Galiläer»). Zum Hahnenschrei als Zeitangabe in der Nacht vgl. [[MRK.13.35]].",
  "Die talmudischen Geschichten sind Jahrhunderte später und überzeichnet; wie sich das galiläische Aramäisch im 1. Jahrhundert genau unterschied, ist nur teilweise bekannt.",
  ["MAT.26.69-MAT.26.75", "MRK.14.70", "MRK.13.35"],
  ["Babylonischer Talmud, Eruvin 53a–b"],
  [("grc", "λαλιά", "Rede, Sprechweise, Mundart")],
  "D Reedwiis vo de Galiläer",
  "«Dini Spraach verratet dich nämli au» ([[MAT.26.73]]): D Galiläer händ es Aramäisch gredt, wo mer z Jerusalem erkännt hät. De Babylonisch Talmud überliferet spööteri Spottgschichte über Galiläer, wo d Chehllüüt nöd underscheide händ und drum falsch verstande worde sind. De Matthäus füegt d Begründig dezue, wo bim Markus fäält ([[MRK.14.70]]: «dänn du bisch au en Galiläer»). Zum Haneschrei als Ziitaagaab i de Nacht vgl. [[MRK.13.35]].",
  "Di talmudische Gschichte sind Jaarhundert spööter und überzeichnet; wie sich s galiläisch Aramäisch im 1. Jaarhundert gnau underschide hät, isch nu teilwiis bekannt.",
  ["Red, Reedwiis, Mundart"]),
 # Kapitel 27
 ("BG-MAT-4020", U(27, 11, 26), "MAT.27.24-MAT.27.25", TEMPLE, "probable", "Händewaschen und die Formel «Sein Blut über uns»",
  "Das Waschen der Hände als Zeichen der Unschuld an einem Blutvergiessen kennt das Gesetz: Wird ein Erschlagener gefunden und ist der Täter unbekannt, waschen die Ältesten der nächsten Stadt ihre Hände und sprechen: «Unsere Hände haben dieses Blut nicht vergossen» ([[DEU.21.6-DEU.21.9]]; vgl. [[PSA.26.6]]; [[PSA.73.13]]). Die Wendung «sein Blut über …» bezeichnet in der Schrift die Verantwortung für einen Tod: Wer sie spricht, übernimmt die Haftung ([[JOS.2.19]]; [[2SA.1.16]]; [[JER.26.15]]; vgl. [[ACT.18.6]]). Matthäus erzählt die Szene in Begriffen der Schrift, die seine jüdisch geprägten Leser kannten.",
  "Ob ein römischer Statthalter eine solche Geste aus dem jüdischen Recht gebrauchte, ist fraglich; die Szene steht nur bei Matthäus. Zu Pilatus siehe BG-MRK-2008, zur Auslegung von [[MAT.27.25]] INT-MAT-4012.",
  ["MAT.27.24-MAT.27.25", "DEU.21.6-DEU.21.9", "PSA.26.6", "PSA.73.13", "JOS.2.19", "2SA.1.16", "JER.26.15", "ACT.18.6"], [],
  [("grc", "ἀπονίπτω", "abwaschen"), ("grc", "ἀθῷος", "unschuldig, straffrei")],
  "Händwäsche und d Formle «Sis Bluet uf üs»",
  "S Wäsche vo de Händ als Zeiche vo de Unschuld a me Bluetvergiesse kännt s Gsetz: Wird en Erschlagne gfunde und isch de Täter unbekannt, wäsched d Ältischte vo de nööchschte Stadt iri Händ und säged: «Öisi Händ händ das Bluet nöd vergosse» ([[DEU.21.6-DEU.21.9]]; vgl. [[PSA.26.6]]; [[PSA.73.13]]). D Wändig «sis Bluet uf …» bezeichnet i de Schrift d Verantwortig für en Tod: Wer si seit, übernimmt d Haftig ([[JOS.2.19]]; [[2SA.1.16]]; [[JER.26.15]]; vgl. [[ACT.18.6]]). De Matthäus verzellt d Szene mit Begriff us de Schrift, wo sini jüdisch prägte Läser kännt händ.",
  "Öb en römische Statthalter e settigi Geschte us em jüdische Rächt bruucht hät, isch fraglich; d Szene staat nu bim Matthäus. Zum Pilatus lueg BG-MRK-2008, zur Uuslegig vo [[MAT.27.25]] INT-MAT-4012.",
  ["abwäsche", "unschuldig, straffrei"]),
 ("BG-MAT-4021", U(27, 1, 10), "MAT.27.7-MAT.27.8", TEMPLE, "possible", "Töpferacker und Blutacker",
  "Nach Matthäus kaufen die Hohepriester mit dem Geld des Judas «den Acker des Töpfers» als Begräbnisplatz für Fremde, also für Pilger und Auswärtige, die in Jerusalem starben ([[MAT.27.7]]). Die Apostelgeschichte nennt den Ort aramäisch «Hakeldamach», «Blutacker» ([[ACT.1.19]]). Seit der Spätantike wird er im Hinnomtal südlich der Altstadt gezeigt. Dort, beim «Scherbentor», liess Jeremia nach [[JER.19.1-JER.19.13]] einen Tonkrug zerbrechen; im Hinnomtal lag auch der Ort Tofet. Geld, das als «Preis für Blut» galt, durfte nicht in den Tempelschatz ([[MAT.27.6]]; vgl. [[DEU.23.18]]).",
  "Die Lage des Ackers ist nur durch spätere Überlieferung bestimmt. Matthäus und die Apostelgeschichte erklären den Namen verschieden: mit dem Blutgeld bzw. mit dem Blut des Judas ([[ACT.1.18-ACT.1.19]]).",
  ["MAT.27.6-MAT.27.10", "ACT.1.18-ACT.1.19", "JER.19.1-JER.19.13", "DEU.23.18"], [],
  [("arc", "חֲקֵל דְּמָא", "Blutacker (aramäisch; Schreibung rekonstruiert)", "ḥăqēl dᵉmāʾ"), ("grc", "Ἁκελδαμάχ", "Hakeldamach (griechische Umschrift)")],
  "Töpferacher und Bluetacher",
  "Nach em Matthäus chaufed d Hoheprieschter mit em Gält vom Judas «de Acher vom Töpfer» als Begräbnisplatz für Frömdi, also für Pilger und Uswärtigi, wo z Jerusalem gstorbe sind ([[MAT.27.7]]). D Aposchtelgschicht nännt de Ort aramäisch «Hakeldamach», «Bluetacher» ([[ACT.1.19]]). Sit de Spöötantike wird er im Hinnomtal südlich vo de Altstadt zeigt. Det, bim «Schärbetor», hät de Jeremia nach [[JER.19.1-JER.19.13]] en Toonchrueg la verbräche; im Hinnomtal isch au de Ort Tofet gläge. Gält, wo als «Pris für Bluet» gulte hät, hät nöd in Tämpelschatz dörfe ([[MAT.27.6]]; vgl. [[DEU.23.18]]).",
  "D Laag vom Acher isch nu dur spööteri Überliferig bestimmt. De Matthäus und d Aposchtelgschicht erklääred de Name verschide: mit em Bluetgält bzw. mit em Bluet vom Judas ([[ACT.1.18-ACT.1.19]]).",
  ["Bluetacher (aramäisch; Schriibig rekonstruiert)", "Hakeldamach (griechischi Umschrift)"]),
 ("BG-MAT-4022", U(27, 32, 44), "MAT.27.33-MAT.27.34", TEMPLE, "possible", "Golgota und der Wein mit Galle",
  "Golgota, aramäisch «Schädel», lag ausserhalb der damaligen Stadtmauer (vgl. [[HEB.13.12]]; [[JHN.19.20]]); seit dem 4. Jahrhundert wird er in der Grabeskirche verehrt, deren Gelände zur Zeit Jesu ausserhalb der Stadtmauer lag. Statt des mit Myrrhe gewürzten Weins bei Markus ([[MRK.15.23]]) nennt Matthäus «Wein, mit Galle vermischt» ([[MAT.27.34]]). Das erinnert an [[PSA.69.21]]: «Sie gaben mir Galle zur Speise und für meinen Durst Essig zu trinken.» Ein betäubender Trank für Sterbende ist in [[PRO.31.6]] erwähnt. Zur Kreuzigung selbst siehe BG-MRK-2010.",
  "Ob die Grabeskirche den historischen Ort bewahrt, ist nicht beweisbar, gilt aber als gut möglich. Was «Galle» (χολή) genau bezeichnet (Bitterstoff, Gift), ist unsicher.",
  ["MAT.27.33-MAT.27.34", "MRK.15.22-MRK.15.23", "PSA.69.21", "PRO.31.6", "HEB.13.12", "JHN.19.17-JHN.19.20"], [],
  [("arc", "גָּלְגָּלְתָּא", "Schädel (aramäisch)", "gulgultāʾ"), ("grc", "χολή", "Galle, Bitterstoff")],
  "Golgota und de Wii mit Galle",
  "Golgota, aramäisch «Schädel», isch usserhalb vo de dameligi Stadtmuur gläge (vgl. [[HEB.13.12]]; [[JHN.19.20]]); sit em 4. Jaarhundert wird er i de Grabeschile verehrt, wo ires Gländ zur Ziit vo Jesus usserhalb vo de Stadtmuur gläge isch. Statt em Wii mit Myrrhe bim Markus ([[MRK.15.23]]) nännt de Matthäus «Wii, mit Galle gmischt» ([[MAT.27.34]]). Das erinneret a [[PSA.69.21]]: «Si händ mir Galle z ässe ggää und für min Durscht Essig z trinke.» En betäubende Trank für Stärbendi isch i [[PRO.31.6]] erwäänt. Zur Chrüüzigung sälber lueg BG-MRK-2010.",
  "Öb d Grabeschile de historisch Ort bewaart, cha mer nöd bewiise, gilt aber als guet möglich. Was «Galle» (χολή) gnau bezeichnet (Bitterstoff, Gift), isch unsicher.",
  ["Schädel (aramäisch)", "Galle, Bitterstoff"]),
 ("BG-MAT-4023", U(27, 62, 66), "MAT.27.62-MAT.27.66", TEMPLE, "possible", "Wache und Siegel am Grab",
  "Pilatus antwortet: «Ihr habt eine Wache» (κουστωδία, aus dem lateinischen custodia, [[MAT.27.65]]). Das Griechische kann auch heissen «Nehmt eine Wache!»; dann stellt Pilatus römische Soldaten zur Verfügung. Dafür spricht, dass die Wächter später «Soldaten» heissen und Ärger mit dem Statthalter fürchten müssen ([[MAT.28.12-MAT.28.14]]); dagegen, dass sie den Hohepriestern berichten ([[MAT.28.11]]), was eher an die Tempelwache denken lässt. Das Versiegeln des Steins, etwa mit einer Schnur und Ton oder Wachs, machte jedes Öffnen sichtbar; so wird auch die Löwengrube verschlossen ([[DAN.6.17]]). Die Grabanlage selbst beschreibt BG-MRK-2012.",
  "Ob eine Grabwache historisch ist, ist umstritten; die Erzählung steht nur bei Matthäus und antwortet auf den Vorwurf, der Leichnam sei gestohlen worden (BG-MAT-4026).",
  ["MAT.27.62-MAT.27.66", "MAT.28.4", "MAT.28.11-MAT.28.15", "DAN.6.17"], [],
  [("grc", "κουστωδία", "Wache (lateinisch custodia)"), ("grc", "σφραγίζω", "versiegeln"), ("lat", "custodia", "Bewachung, Wache", "custodia")],
  "Wach und Sigel am Grab",
  "De Pilatus antwortet: «Ir händ e Wach» (κουστωδία, vom latiinische custodia, [[MAT.27.65]]). S Griechisch cha au heisse «Nämed e Wach!»; dänn stellt de Pilatus römischi Soldate zur Verfüegig. Defür spricht, dass d Wächter spööter «Soldate» heissed und Ärger mit em Statthalter müend fürchte ([[MAT.28.12-MAT.28.14]]); dergäge, dass si de Hoheprieschter Bricht gänd ([[MAT.28.11]]), was eher a d Tämpelwach tänke laat. S Versigle vom Stei, öppe mit ere Schnuer und Toon oder Wachs, hät jedes Uftue sichtbar gmacht; so wird au d Löiegruebe verschlosse ([[DAN.6.17]]). D Grabaalaag sälber beschriibt BG-MRK-2012.",
  "Öb e Grabwach historisch isch, isch umstritte; d Gschicht staat nu bim Matthäus und antwortet uf de Vorwurf, d Liich seg gstole worde (BG-MAT-4026).",
  ["Wach (latiinisch custodia)", "versigle", "Bewachig, Wach"]),
 # Kapitel 28
 ("BG-MAT-4024", U(28, 1, 10), "MAT.28.1-MAT.28.10", TEMPLE, "probable", "Frauen als erste Zeuginnen",
  "Nach Josephus sollte das Zeugnis von Frauen vor Gericht wegen ihres «Leichtsinns» nicht angenommen werden; ähnliche Einschränkungen kennen spätere rabbinische Texte. Dass alle vier Evangelien Frauen als erste am leeren Grab nennen ([[MAT.28.1]]; [[MRK.16.1]]; [[LUK.24.1-LUK.24.10]]; [[JHN.20.1]]), wird darum oft als Hinweis auf eine alte Überlieferung gewertet, die man nicht erfunden hätte. Bei Matthäus sind es Maria aus Magdala und «die andere Maria», die schon bei Kreuz und Grab dabei waren ([[MAT.27.55-MAT.27.56]]; [[MAT.27.61]]); sie erhalten von Engel und Auferwecktem den Auftrag, den Jüngern zu berichten ([[MAT.28.7]]; [[MAT.28.10]]).",
  "Die Einschränkung galt vor Gericht, nicht für jede Mitteilung; wie stark sie das Alltagsleben prägte, ist umstritten. Das Argument der «Peinlichkeit» ist eine historische Wahrscheinlichkeitsüberlegung, kein Beweis. Zum leeren Grab bei Markus siehe FIND-MRK-2014.",
  ["MAT.27.55-MAT.27.61", "MAT.28.1-MAT.28.10", "MRK.16.1-MRK.16.8", "LUK.24.1-LUK.24.11", "JHN.20.1-JHN.20.18"],
  ["Josephus, Jüdische Altertümer 4,219"],
  [],
  "Fraue als erschti Züügine",
  "Nach em Josephus hät s Züügnis vo Fraue vor Gricht wäge irem «Liichtsinn» nöd sölle aagnoo wärde; ähnlichi Iischränkige känned spööteri rabbinischi Text. Dass alli vier Evangelie Fraue als erschti am lääre Grab nänned ([[MAT.28.1]]; [[MRK.16.1]]; [[LUK.24.1-LUK.24.10]]; [[JHN.20.1]]), wird drum oft als Hiiwiis uf e alti Überliferig gwärtet, wo mer nöd erfunde hett. Bim Matthäus sind s d Maria vo Magdala und «di ander Maria», wo scho bi Chrüüz und Grab debii gsii sind ([[MAT.27.55-MAT.27.56]]; [[MAT.27.61]]); si überchömed vom Ängel und vom Uferweckte de Uftrag, s de Jünger z brichte ([[MAT.28.7]]; [[MAT.28.10]]).",
  "D Iischränkig hät vor Gricht gulte, nöd für jedi Mitteilig; wie starch si s Alltagsläbe prägt hät, isch umstritte. S Argument vo de «Pinlichkeit» isch e historischi Wahrschiinlichkeitsüberlegig, kein Bewiis. Zum lääre Grab bim Markus lueg FIND-MRK-2014.",
  []),
 ("BG-MAT-4025", U(28, 16, 20), "MAT.28.19", READERS, "probable", "Taufe auf den dreifachen Namen",
  "Die Taufformel «auf den Namen des Vaters und des Sohnes und des heiligen Geistes» ([[MAT.28.19]]) steht wortgleich in der Didache, einer frühchristlichen Gemeindeordnung, die oft ins späte 1. oder frühe 2. Jahrhundert datiert wird. Die Apostelgeschichte spricht dagegen von einer Taufe «auf den Namen Jesu Christi» oder «des Herrn Jesus» ([[ACT.2.38]]; [[ACT.8.16]]; [[ACT.10.48]]; [[ACT.19.5]]). «Auf den Namen» (εἰς τὸ ὄνομα) bedeutet: in die Zugehörigkeit zu dem, dessen Name genannt wird. Alle bekannten Handschriften von Matthäus haben die dreigliedrige Formel.",
  "Eusebius zitiert den Vers mehrfach in kürzerer Form («macht alle Völker zu Jüngern in meinem Namen», etwa Kirchengeschichte 3,5,2); ob er einen anderen Text kannte oder frei zitierte, ist umstritten. Wie sich die beiden Taufformeln geschichtlich zueinander verhalten, ist offen.",
  ["MAT.28.19", "ACT.2.38", "ACT.8.16", "ACT.10.48", "ACT.19.5"],
  ["Didache 7,1", "Eusebius, Kirchengeschichte 3,5,2"],
  [("grc", "εἰς τὸ ὄνομα", "auf den Namen; in die Zugehörigkeit zu"), ("grc", "βαπτίζω", "taufen, eintauchen")],
  "Taufi uf de driifach Name",
  "D Taufformle «uf de Name vom Vatter und vom Sohn und vom heilige Geischt» ([[MAT.28.19]]) staat wortgliich i de Didache, ere früechrischtliche Gmeindsornig, wo mer oft is spoot 1. oder früe 2. Jaarhundert datiert. D Aposchtelgschicht redt dergäge vo ere Taufi «uf de Name vo Jesus Christus» oder «vom Herr Jesus» ([[ACT.2.38]]; [[ACT.8.16]]; [[ACT.10.48]]; [[ACT.19.5]]). «Uf de Name» (εἰς τὸ ὄνομα) bedüütet: i d Zuegehörigkeit zu dem, wo sin Name gnännt wird. Alli bekannte Handschrifte vom Matthäus händ di driigliedrig Formle.",
  "De Eusebius zitiert de Värs meermal i chürzerer Form («mached alli Völker zu Jünger i mim Name», öppe Chilegschicht 3,5,2); öb er en andere Text kännt oder frei zitiert hät, isch umstritte. Wie sich di beide Taufformle gschichtlich zunenand verhalted, isch offe.",
  ["uf de Name; i d Zuegehörigkeit zu", "taufe, iituuche"]),
 ("BG-MAT-4026", U(28, 11, 15), "MAT.28.11-MAT.28.15", READERS, "probable", "Der Vorwurf des Leichendiebstahls",
  "Matthäus schliesst den Bericht der Wache mit der Bemerkung, «diese Geschichte» habe sich «bei Juden verbreitet bis zum heutigen Tag» ([[MAT.28.15]]). Der Vorwurf, die Jünger hätten den Leichnam gestohlen, ist auch später bezeugt: Justin der Märtyrer schreibt um 160 n. Chr. im Dialog mit dem Juden Tryphon, man verbreite, die Jünger hätten Jesus nachts aus dem Grab gestohlen und behauptet, er sei auferstanden. Die Erzählung von der Grabwache ([[MAT.27.62-MAT.27.66]]; [[MAT.28.11-MAT.28.15]]) antwortet auf diesen Vorwurf. Sie zeigt zugleich, dass beide Seiten voraussetzten, das Grab sei leer gewesen.",
  "Justin ist ein christlicher Zeuge und kann von Matthäus abhängig sein; seine Angabe ist kein unabhängiger jüdischer Beleg. «Bei Juden» (παρὰ Ἰουδαίοις) ist ohne Artikel; ob alle Juden oder bestimmte Kreise gemeint sind, ist offen.",
  ["MAT.27.62-MAT.27.66", "MAT.28.11-MAT.28.15"],
  ["Justin, Dialog mit Tryphon 108"],
  [("grc", "κλέπτω", "stehlen")],
  "De Vorwurf vom Liichediebstahl",
  "De Matthäus schlüüsst de Bricht vo de Wach mit de Bemerkig, «die Gschicht» heg sich «bi Jude verbreitet bis hüt» ([[MAT.28.15]]). De Vorwurf, d Jünger hebed d Liich gstole, isch au spööter bezüügt: De Justin de Märtyrer schriibt um 160 n. Chr. im Dialog mit em Jud Tryphon, mer verbreiti, d Jünger hebed de Jesus znacht us em Grab gstole und behauptet, er seg uferstande. D Gschicht vo de Grabwach ([[MAT.27.62-MAT.27.66]]; [[MAT.28.11-MAT.28.15]]) antwortet uf dä Vorwurf. Si zeigt zuglich, dass beid Siite vorusgsetzt händ, s Grab seg läär gsii.",
  "De Justin isch en chrischtliche Züüg und möglicherwiis abhängig vom Matthäus; sini Aagaab isch kein unabhängige jüdische Beleg. «Bi Jude» (παρὰ Ἰουδαίοις) isch ohni Artikel; öb alli Jude oder bestimmti Chreis gmeint sind, isch offe.",
  ["stäle"]),
]

