SUMMARIES = [
 ("SUM-CH-MAT-022",
  "Jesus erzählt das Gleichnis vom König, der zum Hochzeitsfest seines Sohnes einlädt: Die Geladenen kommen nicht und töten seine Knechte; der König schickt seine Truppen und zündet ihre Stadt an, lässt alle von den Strassen einladen und befiehlt, einen Gast ohne Hochzeitskleid hinauszuwerfen. Dann fragen ihn Jünger der Pharisäer mit den Herodianern nach der Steuer für den Kaiser, Sadduzäer nach der Auferstehung und ein Gesetzeslehrer nach dem grössten Gebot; Jesus antwortet mit «Gebt dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist», mit dem Gott der Lebenden und mit den Geboten, Gott und den Nächsten zu lieben. Zuletzt fragt er die Pharisäer, wie der Christus Davids Sohn sein kann, wenn David ihn «Herr» nennt; danach wagt niemand mehr, ihn zu fragen.",
  "De Jesus verzellt s Gliichnis vom König, wo as Hochziitfäscht vo sim Sohn iiladt: D Iigladne chömed nöd und bringed sini Chnächt um; de König schickt sini Truppe und zündt iri Stadt aa, laat alli vo de Strasse iilade und befiilt, en Gascht ohni Hochziitgwand usezrüere. Dänn fröged en Jünger vo de Pharisäer mit de Herodianer nach de Stüür für de Kaiser, Sadduzäer nach de Uferstehig und en Gsetzeslehrer nach em gröschte Gebot; de Jesus antwortet mit «Gänd em Kaiser, was em Kaiser ghört, und Gott, was Gott ghört», mit em Gott vo de Läbige und mit de Gebot, Gott und de Nächscht z liebe. Zletscht fröget er d Pharisäer, wie de Christus de Sohn vom David cha sii, wänn de David en «Herr» nännt; dänn traut sich niemer meh, en z fröge."),
 ("SUM-CH-MAT-023",
  "Jesus spricht zu den Menschenmengen und Jüngern über die Schriftgelehrten und Pharisäer: Was sie sagen, sollen sie tun und halten, aber nicht nach ihren Werken handeln, denn sie reden und tun es nicht. Die Jünger sollen sich nicht Rabbi oder Lehrmeister nennen lassen und niemanden auf der Erde Vater nennen; der Grösste soll Diener sein. Dann ruft er den Schriftgelehrten und Pharisäern sieben Mal «Wehe» zu, nennt sie Heuchler und blinde Führer und kündigt an, dass alles gerechte Blut über dieses Geschlecht kommen wird. Am Schluss klagt er über Jerusalem, das die Propheten tötet: Ihr Haus wird verödet überlassen, und sie werden ihn nicht mehr sehen, bis sie sagen: «Gesegnet sei der, der kommt im Namen des Herrn!»",
  "De Jesus redt zu de Lüüt und zu de Jünger über d Schriftgelehrte und d Pharisäer: Was die säged, söled si tue und halte, aber nöd nach irne Wärch handle, dänn si reded und tüend s nöd. D Jünger söled sich nöd Rabbi oder Lehrmeischter nänne laa und niemer uf de Ärde Vatter nänne; de Gröscht söll Diener sii. Dänn rüeft er de Schriftgelehrte und de Pharisäer siebe Mal «Weh» zue, nännt si Hüüchler und blindi Füerer und chündet aa, dass alles grächte Bluet über die Generation chunnt. Am Schluss klagt er über Jerusalem, wo d Prophete umbringt: Ires Huus wird läär und öd überlaa, und si wärded en nüme gseh, bis si säged: «Gsägnet seg dä, wo chunnt im Name vom Herr!»"),
 ("SUM-CH-MAT-024",
  "Jesus kündigt an, dass vom Tempel kein Stein auf dem anderen bleiben wird. Auf dem Ölberg fragen ihn die Jünger nach der Zeit und nach dem Zeichen seines Kommens und der Vollendung der Weltzeit. Er warnt vor Verführern und spricht von Kriegen, Verfolgung, der Verkündigung des Evangeliums an alle Völker, dem Gräuel der Verwüstung und einer grossen Bedrängnis; danach wird der Menschensohn mit Macht und Herrlichkeit auf den Wolken kommen und seine Auserwählten sammeln. Wie am Feigenbaum sollen sie erkennen, dass er nahe ist; dieses Geschlecht wird nicht vergehen, bis all das geschieht. Tag und Stunde aber kennt niemand ausser dem Vater; darum sollen die Jünger wachen und wie ein treuer Knecht bereit sein.",
  "De Jesus chündet aa, dass vom Tämpel kei Stei uf em andere bliibt. Uf em Ölberg fröged en d Jünger nach de Ziit und nach em Zeiche vo sinere Aachunft und vo de Vollendig vo de Wältziit. Er warnt vor Verfüerer und redt vo Chrieg, Verfolgig, vo de Verchündigung vom Evangelium a alli Völker, vom Gröiel vo de Verwüeschtig und vo ere grosse Bedrängnis; dänn chunnt de Mänschesohn mit Macht und Herrlichkeit uf de Wolke und sammlet sini Userwählte. Wie am Fiigebaum söled si erkänne, dass er nööch isch; die Generation vergaat nöd, bis das alles passiert. Tag und Stund aber kännt niemer usser em Vatter; drum söled d Jünger wach bliibe und wie en treue Chnächt parat sii."),
 ("SUM-CH-MAT-025",
  "Jesus setzt die Rede mit Gleichnissen fort: Von zehn Jungfrauen, die den Bräutigam erwarten, gehen nur die fünf klugen, die Öl mitgenommen haben, mit ihm zur Hochzeit hinein; die törichten stehen vor verschlossener Tür. Ein Herr vertraut seinen Knechten Talente an; zwei vermehren sie und werden gelobt, der dritte vergräbt sein Talent aus Furcht, und der Herr befiehlt, ihn hinauszuwerfen. Zuletzt kündigt Jesus an, dass der Menschensohn als König alle Völker richten wird: Was sie einem seiner geringsten Brüder getan oder nicht getan haben, haben sie ihm getan oder nicht getan; die einen gehen in ewiges Leben, die anderen in ewige Strafe.",
  "De Jesus füert d Red mit Gliichnis wiiter: Vo zäh Jumpfere, wo uf de Brüütigam warted, gönd nu di föif gschiide, wo Öl mitgnoo händ, mit ihm a d Hochziit ine; di tumme stönd vor de zueglossne Tür. En Herr vertraut sine Chnächt Talänt aa; zwei vermehred si und wärded globt, de dritt vergrabt sis Talänt us Angscht, und de Herr befiilt, en usezrüere. Zletscht chündet de Jesus aa, dass de Mänschesohn als König alli Völker richtet: Was si eim vo sine chliinschte Brüedere gmacht oder nöd gmacht händ, händ si ihm gmacht oder nöd gmacht; di einte gönd is ewig Läbe, di andere i d ewig Straf."),
 ("SUM-CH-MAT-026",
  "Jesus kündigt an, dass er in zwei Tagen am Passa ausgeliefert und gekreuzigt wird; die Hohepriester und Ältesten beraten, wie sie ihn mit List töten können. In Betanien giesst eine Frau ihm kostbares Salböl über den Kopf, was er als Vorbereitung für sein Begräbnis deutet; Judas lässt sich von den Hohepriestern dreissig Silberstücke geben, um ihn auszuliefern. Beim Passamahl kündigt Jesus an, dass einer der Zwölf ihn ausliefern wird, und gibt den Jüngern Brot und Becher als seinen Leib und sein Blut des Bundes zur Vergebung der Sünden. In Getsemani betet er drei Mal, während die Jünger schlafen; Judas liefert ihn mit einem Kuss aus, und alle Jünger fliehen. Vor dem Hohen Rat antwortet Jesus auf die Frage, ob er der Christus sei, «Du hast es gesagt» und kündigt das Kommen des Menschensohns an; sie erklären, er habe den Tod verdient. Petrus verleugnet ihn drei Mal und weint bitterlich.",
  "De Jesus chündet aa, dass er in zwei Täg am Passa usgliferet und gchrüüziget wird; d Hoheprieschter und d Ältischte beraated, wie si en mit Lischt chönted umbringe. Z Betanie schüttet em e Frau tüürs Salböl über de Chopf, und er seit, si heg s für sini Beerdigung gmacht; de Judas laat sich vo de Hoheprieschter driissg Silberstück gää, zum en uslifere. Bim Passamahl chündet de Jesus aa, dass eine vo de Zwölf en wird uslifere, und git de Jünger Broot und Bächer als sin Liib und sis Bluet vom Bund zur Vergäbig vo de Sünde. In Getsemani bättet er drüü Mal, wäred d Jünger schlafed; de Judas liferet en mit eme Kuss us, und alli Jünger flüchted. Vor em Hohe Raat antwortet de Jesus uf d Frag, öb er de Christus seg, «Du häsch es gseit» und chündet d Aachunft vom Mänschesohn aa; si erklääred, er heg de Tod verdient. De Petrus verleugnet en drüü Mal und briegget bitterlich."),
 ("SUM-CH-MAT-027",
  "Am Morgen liefern die Hohepriester und Ältesten Jesus an Pilatus aus. Judas bereut, wirft die Silberstücke in den Tempel und erhängt sich; mit dem Geld kaufen die Hohepriester den Töpferacker. Pilatus fragt Jesus, ob er der König der Juden sei; die Menge, von den Hohepriestern und Ältesten überredet, verlangt Barabbas und die Kreuzigung Jesu. Pilatus wäscht sich die Hände und erklärt sich unschuldig, das Volk ruft: «Sein Blut über uns und über unsere Kinder!» Pilatus lässt Barabbas frei und liefert Jesus nach der Geisselung zur Kreuzigung aus. Soldaten verspotten ihn; auf Golgota wird er gekreuzigt und verhöhnt. Nach dem Ruf «Mein Gott, mein Gott, wozu hast du mich verlassen?» schreit er noch einmal und stirbt; der Vorhang des Tempels zerreisst, die Erde bebt, Gräber öffnen sich, und der Hauptmann und die Wachen sagen: «Wahrhaftig, dieser war Gottes Sohn!» Frauen aus Galiläa schauen von ferne zu. Josef von Arimatäa legt den Leib in sein Grab; auf Bitte der Hohepriester und Pharisäer wird das Grab versiegelt und bewacht.",
  "Am Morge lifered d Hoheprieschter und d Ältischte de Jesus em Pilatus us. De Judas bereut, rüert d Silberstück in Tämpel und hänkt sich uf; mit em Gält chaufed d Hoheprieschter de Töpferacher. De Pilatus fröget de Jesus, öb er de König vo de Jude seg; d Mängi, vo de Hoheprieschter und Ältischte überredt, verlangt de Barabbas und d Chrüüzigung vo Jesus. De Pilatus wäscht sich d Händ und erklärt sich unschuldig, s Volk rüeft: «Sis Bluet uf üs und uf öisi Chind!» De Pilatus laat de Barabbas frei und liferet de Jesus nach em Geissle zur Chrüüzigung us. Soldate verspotted en; uf Golgota wird er gchrüüziget und verhöhnt. Nach em Ruef «Min Gott, min Gott, für was häsch du mich verlaa?» schreit er nomal und stirbt; de Vorhang vom Tämpel verriisst, d Ärde bebt, Greber gönd uf, und de Hauptmaa und d Wächter säged: «Würkli, dä isch Gottes Sohn gsii!» Fraue us Galiläa lueged vo wiitem zue. De Josef vo Arimatäa leit de Liib i sis Grab; uf d Bitt vo de Hoheprieschter und Pharisäer wird s Grab versiglet und bewacht."),
 ("SUM-CH-MAT-028",
  "Am ersten Tag der Woche kommen Maria aus Magdala und die andere Maria zum Grab. Ein Engel wälzt unter einem Erdbeben den Stein weg; die Wächter erstarren vor Furcht, und der Engel sagt den Frauen, Jesus sei auferweckt worden und gehe den Jüngern nach Galiläa voraus. Auf dem Weg begegnet ihnen Jesus selbst und schickt sie zu seinen Brüdern. Die Hohepriester bezahlen die Soldaten, damit sie sagen, die Jünger hätten ihn nachts gestohlen. Auf einem Berg in Galiläa werfen sich die elf Jünger vor Jesus nieder, einige aber zweifeln; er sagt, ihm sei alle Vollmacht gegeben, sendet sie, alle Völker zu Jüngern zu machen, zu taufen und zu lehren, und verspricht, bei ihnen zu sein alle Tage bis zur Vollendung der Weltzeit.",
  "Am erschte Tag vo de Wuche chömed d Maria vo Magdala und di ander Maria zum Grab. En Ängel wälzt under eme Ärdbebe de Stei ewägg; d Wächter erstarred vor Angscht, und de Ängel seit de Fraue, de Jesus seg uferweckt worde und gang de Jünger voruus nach Galiläa. Underwägs begägnet ene de Jesus sälber und schickt si zu sine Brüedere. D Hoheprieschter zaled d Soldate, damit si säged, d Jünger hebed en znacht gstole. Uf eme Bärg z Galiläa wärfed sich di elf Jünger vor em Jesus nider, es paar aber zwiifled; er seit, ihm seg alli Vollmacht ggää, schickt si, alli Völker zu Jünger z mache, z taufe und z lehre, und verspricht, bi ene z sii alli Täg bis zur Vollendig vo de Wältziit."),
]


def run():
    extra = sorted((p.stem for p in (D / "translations").rglob("TRANS-MAT-02*-WORKING.json")
                    if re.fullmatch(r"TRANS-MAT-02[2-8]-\d{3}-\d{3}-(DE|GSW-ZH)-WORKING", p.stem)),
                   key=lambda x: ("-GSW-" in x, x))
    for sid in ("STUDY-MAT-0005",):
        p = D / "studies" / f"{sid}.json"
        if p.exists() and "Matthäus 22–28" not in json.loads(p.read_text(encoding="utf-8")).get("title", ""):
            raise SystemExit(f"{sid} existiert schon mit anderem Inhalt; nicht überschreiben")
    for sid, _, _ in SUMMARIES:
        p = D / "summaries" / f"{sid}.json"
        if p.exists() and "TAG-MATTHEW" not in json.loads(p.read_text(encoding="utf-8")).get("tags", []):
            raise SystemExit(f"{sid} existiert schon aus anderer Quelle; nicht überschreiben")
    _study.write_study({"TAGS": TAGS, "CONTEXT": CONTEXT, "FINDINGS": FINDINGS, "INTERPRETATIONS": INTERPRETATIONS,
                        "PRINCIPLES": PRINCIPLES, "APPLICATIONS": APPLICATIONS, "QUESTIONS": QUESTIONS,
                        "RELATIONS": RELATIONS, "BACKGROUND": BACKGROUND, "SUMMARIES": SUMMARIES,
                        "SOURCE_CHECKS": SOURCE_CHECKS,
                        "STUDY": ("STUDY-MAT-0005", "Matthäus 22–28: Studieninhalte", CHAPTERS[22],
                                  extra + [s[0] for s in SUMMARIES],
                                  ["Mundart muttersprachlich prüfen",
                                   "Fachliche Prüfung der Deutungen und des Hintergrunds",
                                   "Sekundärangaben (Septuaginta zu Dtn 6,5 und Dan 7,14; Mischna- und Talmudstellen; "
                                   "Josephus-Stellen; Funde von Chorazin und Qumran; Lesarten zu Mt 27,9) an Fachquellen nachprüfen",
                                   "Zählungen beruhen auf MACULA-Lemmata zum SBLGNT; andere Editionen können abweichen"])},
                       "Matthäus 22–28")


if __name__ == "__main__":
    run()
